module main
const max_ops = 128
struct Node { mut: key i64; left int; right int; parent int; red bool }
fn left_rotate(mut t []Node, mut root int, x int) { y:=t[x].right;t[x].right=t[y].left;if t[y].left!=0 {t[t[y].left].parent=x};t[y].parent=t[x].parent;if t[x].parent==0 {root=y} else if x==t[t[x].parent].left {t[t[x].parent].left=y} else {t[t[x].parent].right=y};t[y].left=x;t[x].parent=y }
fn right_rotate(mut t []Node, mut root int, y int) { x:=t[y].left;t[y].left=t[x].right;if t[x].right!=0 {t[t[x].right].parent=y};t[x].parent=t[y].parent;if t[y].parent==0 {root=x} else if y==t[t[y].parent].right {t[t[y].parent].right=x} else {t[t[y].parent].left=x};t[x].right=y;t[y].parent=x }
fn find_node(t []Node, root_in int, key i64) int {mut root:=root_in;for root!=0&&t[root].key!=key {root=if key<t[root].key {t[root].left} else {t[root].right}};return root }
fn insert_node(mut t []Node, mut root int, initial_z int) {mut z:=initial_z;mut y:=0;mut x:=root;for x!=0 {y=x;x=if t[z].key<t[x].key {t[x].left} else {t[x].right}};t[z].parent=y;if y==0 {root=z} else if t[z].key<t[y].key {t[y].left=z} else {t[y].right=z};t[z].left=0;t[z].right=0;t[z].red=true;for t[t[z].parent].red {p:=t[z].parent;g:=t[p].parent;if p==t[g].left {y=t[g].right;if t[y].red {t[p].red=false;t[y].red=false;t[g].red=true;z=g} else {if z==t[p].right {z=p;left_rotate(mut t,mut root,z)};p=t[z].parent;g=t[p].parent;t[p].red=false;t[g].red=true;right_rotate(mut t,mut root,g)}} else {y=t[g].left;if t[y].red {t[p].red=false;t[y].red=false;t[g].red=true;z=g} else {if z==t[p].left {z=p;right_rotate(mut t,mut root,z)};p=t[z].parent;g=t[p].parent;t[p].red=false;t[g].red=true;left_rotate(mut t,mut root,g)}}};t[root].red=false }
fn minimum(t []Node, start int) int {mut x:=start;for t[x].left!=0 {x=t[x].left};return x}
fn transplant(mut t []Node, mut root int, u int, v int) {if t[u].parent==0 {root=v} else if u==t[t[u].parent].left {t[t[u].parent].left=v} else {t[t[u].parent].right=v};t[v].parent=t[u].parent}
fn delete_fix(mut t []Node, mut root int, start int) {mut x:=start;for x!=root&&!t[x].red {p:=t[x].parent;if x==t[p].left {mut w:=t[p].right;if t[w].red {t[w].red=false;t[p].red=true;left_rotate(mut t,mut root,p);w=t[t[x].parent].right};if !t[t[w].left].red&&!t[t[w].right].red {t[w].red=true;x=t[x].parent} else {if !t[t[w].right].red {t[t[w].left].red=false;t[w].red=true;right_rotate(mut t,mut root,w);w=t[t[x].parent].right};p=t[x].parent;t[w].red=t[p].red;t[p].red=false;t[t[w].right].red=false;left_rotate(mut t,mut root,p);x=root}} else {mut w:=t[p].left;if t[w].red {t[w].red=false;t[p].red=true;right_rotate(mut t,mut root,p);w=t[t[x].parent].left};if !t[t[w].right].red&&!t[t[w].left].red {t[w].red=true;x=t[x].parent} else {if !t[t[w].left].red {t[t[w].right].red=false;t[w].red=true;left_rotate(mut t,mut root,w);w=t[t[x].parent].left};p=t[x].parent;t[w].red=t[p].red;t[p].red=false;t[t[w].left].red=false;right_rotate(mut t,mut root,p);x=root}}};t[x].red=false }
fn delete_node(mut t []Node, mut root int, z int) {mut y:=z;mut x:=0;mut was_red:=t[y].red;if t[z].left==0 {x=t[z].right;transplant(mut t,mut root,z,t[z].right)} else if t[z].right==0 {x=t[z].left;transplant(mut t,mut root,z,t[z].left)} else {y=minimum(t,t[z].right);was_red=t[y].red;x=t[y].right;if t[y].parent==z {t[x].parent=y} else {transplant(mut t,mut root,y,t[y].right);t[y].right=t[z].right;t[t[y].right].parent=y};transplant(mut t,mut root,z,y);t[y].left=t[z].left;t[t[y].left].parent=y;t[y].red=t[z].red};if !was_red {delete_fix(mut t,mut root,x)} }
fn put_i64(out &u8, offset int, value i64) {bits:=u64(value);for i in 0..8 {unsafe {out[offset+i]=u8(bits>>(i*8))}}}
[export: 'red_black_tree_unique_key_ops']
pub fn red_black_tree_unique_key_ops(input &i64, length usize, output &u8, capacity usize) i64 {
 if isnil(input)||length<1 {return -1};n64:=unsafe{input};if n64<0||n64>max_ops||length!=usize(1+2*n64) {return -1};n:=int(n64);mut active:=[]i64{len: max_ops};mut ac:=0;mut sc:=0
 for i in 0..n {op:=unsafe{input[1+2*i]};key:=unsafe{input[2+2*i]};if op<0||op>2||key<i32(min)||key>i32(max) {return -1};mut found:=ac;for j in 0..ac {if active[j]==key {found=j;break}};if op==0 {if found!=ac||ac>=max_ops {return -1};active[ac]=key;ac++} else if op==1 {sc++} else {if found==ac {return -1};for j in found+1..ac {active[j-1]=active[j]};ac--}}
 mut t:=[]Node{len:max_ops+1};mut root:=0;mut next:=1;mut results:=[]i64{len:max_ops};mut rc:=0
 for i in 0..n {op:=unsafe{input[1+2*i]};key:=unsafe{input[2+2*i]};if op==0 {t[next].key=key;insert_node(mut t,mut root,next);next++} else if op==1 {results[rc]=if find_node(t,root,key)!=0 {1} else {0};rc++} else {delete_node(mut t,mut root,find_node(t,root,key))}}
 bytes:=(2+ac+sc)*8;if isnil(output)||capacity<usize(bytes) {return -2};put_i64(output,0,i64(ac));mut stack:=[]int{len:max_ops};mut top:=0;mut out:=1;mut current:=root;for current!=0||top>0 {for current!=0 {stack[top]=current;top++;current=t[current].left};top--;current=stack[top];put_i64(output,out*8,t[current].key);out++;current=t[current].right};put_i64(output,out*8,i64(sc));out++;for i in 0..sc {put_i64(output,out*8,results[i]);out++};return i64(bytes)
}
